const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sierra Nevada region
  const sierra = ee.Geometry.Rectangle([-121.5, 37.5, -118.5, 40.5]);

  // 2. Define dates
  const date1 = '2022-01-01';
  const date2 = '2022-04-01';
  const date3 = '2022-05-04';

  try {
    // 3. Get MODIS snow cover data
    const getSnowCover = (date) => {
      const col = ee.ImageCollection('MODIS/006/MOD10A1')
        .filterDate(date, ee.Date(date).advance(1, 'day'))
        .filterBounds(sierra);

      return col;
    };

    const col1 = getSnowCover(date1);
    const col2 = getSnowCover(date2);
    const col3 = getSnowCover(date3);

    const size1 = await col1.size().getInfo();
    const size2 = await col2.size().getInfo();
    const size3 = await col3.size().getInfo();

    console.log(`Jan 1 Images: ${size1}`);
    console.log(`Apr 1 Images: ${size2}`);
    console.log(`May 4 Images: ${size3}`);

    // Check for empty collections
    if (size1 === 0 || size2 === 0 || size3 === 0) {
      console.log("Missing data for one or more dates.");
      console.log("<answer>C1</answer>");
      return;
    }

    // 4. Process snow cover with cloud masking
    const processSnow = (collection) => {
      const img = collection.first();
      const snow = img.select('NDSI_Snow_Cover');
      const qa = img.select('NDSI_Snow_Cover_Basic_QA');

      // Mask clouds and invalid data (QA: 0=best, 1=good, 2=ok, 3=poor, 4-255=other)
      const mask = qa.lte(2);
      return snow.updateMask(mask);
    };

    const snow1 = processSnow(col1);
    const snow2 = processSnow(col2);
    const snow3 = processSnow(col3);

    // 5. Calculate statistics
    const stats1 = await snow1.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: sierra,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const stats2 = await snow2.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: sierra,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const stats3 = await snow3.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: sierra,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const mean1 = stats1.NDSI_Snow_Cover_mean;
    const count1 = stats1.NDSI_Snow_Cover_count;
    const mean2 = stats2.NDSI_Snow_Cover_mean;
    const count2 = stats2.NDSI_Snow_Cover_count;
    const mean3 = stats3.NDSI_Snow_Cover_mean;
    const count3 = stats3.NDSI_Snow_Cover_count;

    console.log(`Jan 1: Mean=${mean1?.toFixed(2)}%, Pixels=${count1}`);
    console.log(`Apr 1: Mean=${mean2?.toFixed(2)}%, Pixels=${count2}`);
    console.log(`May 4: Mean=${mean3?.toFixed(2)}%, Pixels=${count3}`);

    // Check for no valid pixels
    if (count1 === 0 || count2 === 0 || count3 === 0) {
      console.log("No valid pixels after cloud masking.");
      console.log("<answer>C2</answer>");
      return;
    }

    // Check for calculation failure
    if (mean1 === null || mean1 === undefined || 
        mean2 === null || mean2 === undefined ||
        mean3 === null || mean3 === undefined) {
      console.log("Calculation returned invalid values.");
      console.log("<answer>C3</answer>");
      return;
    }

    // 6. Compare: Was Jan 1 > Apr 1 AND Jan 1 > May 4?
    if (mean1 > mean2 && mean1 > mean3) {
      console.log("January had more snow than both April and May.");
      console.log("<answer>A</answer>");
    } else {
      console.log("January did not have more snow than both dates.");
      console.log("<answer>B</answer>");
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
